namespace Gameworld.Domain;

// The default list of resources: the 27 generated resources of docs/map-generation.md Appendix G.3,
// in the order of the resource index, each with every variant the generation can give it: the crops
// of Appendix B in table order, then the variants of Appendix D in the order of the rules. Every
// resource and every variant has a description (what it is and looks like where it is won, in a
// medieval world with some magic) and a lore (what the peoples of docs/races-basis.md make of it).
// No doc holds them: they are written here. The arcane materials that are a kind of the default
// flora take both texts of that kind.

public sealed partial record ResourceParameters
{
    /// <summary>The default list: the 27 generated resources and their 323 variants.</summary>
    public static IReadOnlyList<ResourceParameters> Defaults { get; } =
    [
        R(Resource.Grain, "Grain",
        [
            V("bread wheat", "Tall golden wheat with plump beardless ears, grown on good ploughland. Its flour makes the white loaf that rises.", "White bread is for the lord's table. Midlanders reckon a man's standing by the colour of his loaf."),
            V("durum wheat", "Hard wheat of dry sunny land, with long dark beards on the ear and amber, glassy grains. Ground for flat bread, groats and paste.", "The Saltroad folk roll it into grains by hand and steam it, and carry it dried across the desert."),
            V("barley", "A low pale-gold grain with long silky beards that nod in the wind. It takes cold, drought and poor soil, and is malted for ale and boiled for porridge.", "The first grain to be sown and the first to be brewed. Dwarves keep seven years of it behind the gate."),
            V("rye", "A tall, thin, grey-green grain of cold and sandy land, with slender bearded ears. It gives a dark, heavy, sour bread.", "The bread of the north and of the poor. In a wet year a black spur grows in the ear, and a village that eats it burns and dances."),
            V("oats", "A grain with loose, drooping heads of small husked seeds, grown in cool wet land. Food for horses, and porridge and flat cakes for people.", "Fed to horses in the south and to people in the north, as southerners like to point out. Hearthbloods eat it by the pot, twice a day."),
            V("paddy rice", "Bright green rice standing in flooded, banked fields that mirror the sky, on valley floors and hillside terraces. The ears droop gold at harvest.", "The Canal folk built an empire to keep the banks mended. The Rainkeepers catch a season's rain in ten thousand reservoirs for it."),
            V("maize", "Stalks taller than a person with broad leaves and thick cobs of yellow, white or red kernels wrapped in husks.", "It must be planted by hand, seed by seed. The peoples who grow it say the first humans were made of its dough."),
            V("sorghum", "A grain of hot dry land, taller than a person, with a heavy head of round red or white seeds at the top of a cane-like stalk.", "The Sunlanders brew it into a thick, sour beer, and a day's work is paid with a pot of it."),
            V("pearl millet", "A grain of the driest farmland: tall stalks that end in a dense spike like a bulrush, set with small pearl-grey seeds.", "It grows where nothing else will, at the edge of the sand. The Saltroad folk call it the grain that asks for nothing."),
            V("finger millet", "A short millet of tropical hills, whose head spreads like the fingers of a hand, curled inward and set with tiny red-brown seeds.", "It keeps in the granary for ten years. A hill village that has it does not fear one bad monsoon."),
            V("proso millet", "A quick millet of the steppe, knee to waist high, with drooping bushy heads of small round golden seeds. It ripens in a short summer.", "The Grass riders sow it, ride away and come back to reap it. It is the only farming they admit to."),
            V("buckwheat", "A low plant with red stems, heart-shaped leaves and white flowers thick with bees, grown on poor cold soil. The dark three-cornered seeds are ground for cakes and porridge.", "The crop of new clearings and bad land. Its honey is dark and strong, and the Northmen like it so."),
            V("fonio", "A fine grass grown on poor sandy soil in the savanna, with seeds as small as sand. It ripens before any other grain, in the hungry weeks.", "The Sunlanders say the world was made from a grain of it. It is served to chiefs and to guests."),
            V("teff", "A delicate highland grass with feathery heads and seeds smaller than a pinhead, white or red-brown. Ground for a sour, spongy flat bread.", "A lost handful sows a field. Highland peoples carried it in a fold of cloth through the Ashen Years."),
            V("quinoa", "A leafy plant of high cold plateaus, waist high, with great seed heads of red, purple, yellow and white. The small round seeds are boiled like grain.", "The mother grain of the high plateaus. The first furrow of the year is opened by the ruler, with a spade of gold."),
        ], "The cereals a land is sown with: fields of standing corn that turn from green to gold, cut with sickle and scythe and threshed on the barn floor. The bread, the porridge and the ale of most people.", "Every calendar is a grain calendar, and every tax began as a share of the threshing floor. A people is known by its bread: the Catfolk, who cannot eat grain, are trusted to guard it."),
        R(Resource.Produce, "Produce",
        [
            V("potato", "A low leafy plant grown in earthed-up ridges on cool hills, with white or purple flowers. The brown tubers are dug from the soil in autumn.", "Armies trample a wheat field, and leave a potato field alone because they do not know what is under it."),
            V("cassava", "A woody tropical shrub, taller than a person, with hand-shaped leaves. Its long brown roots are white inside, and are grated and pressed to take out the poison.", "Badly prepared, it kills. The Bitterbloods eat it raw and think nothing of it."),
            V("sweet potato", "A creeping vine with heart-shaped leaves that covers the ground in warm lands. Its swollen roots are red-skinned with orange or white flesh.", "It grows on poor land in a famine year, and the Canal folk credit it with a doubling of their numbers."),
            V("greater yam", "A climbing vine grown on poles from mounds of earth in wet tropical land. Its rough brown tubers can be as long as an arm.", "A man shows his best yams at the harvest feast and is ranked by them. The yam is a man's crop, and the other roots are women's."),
            V("taro", "A plant of wet ground and pond fields, with huge heart-shaped leaves on long stalks. The grey corm at its foot is boiled or pounded.", "On the islands it is the elder brother of the people, and no one quarrels while the bowl is open."),
            V("banana and plantain", "Tall soft-stemmed plants with great tattered leaves, grown beside the house in hot wet land. Each bears one hanging bunch of green or yellow fruit.", "A grove is planted at a birth. Its beer is the drink of every bargain in the wet highlands."),
            V("sago palm", "A palm of tropical swamps, felled just before it flowers. Its trunk is split and the pith is washed to a white starch.", "One palm feeds a family for a month. The Shoalfolk say a people with sago has no need of a field."),
            V("faba bean", "An upright bean with grey-green leaves and white flowers marked with black, grown in cool lands. The fat pods hold broad flat beans.", "The dead are said to live in beans, and some sects will not eat them. A bean baked in a cake makes a king for a night."),
            V("pea", "A climbing plant with curling tendrils, grown on sticks in fields and gardens of cool lands. The peas are dried and boiled to pottage.", "Pease pottage is the daily dish of the Midlander poor, hot or cold, and nine days old in the rhyme."),
            V("lentil", "A low, fine-leaved plant of dry lands, with small pods that hold two flat round seeds each: brown, green or red.", "The food of mourners, and of a birthright sold for a bowl of it. The Saltroad folk eat it every day."),
            V("chickpea", "A low bushy plant of dry warm land with feathery leaves and puffed pods, each with one or two round beaked seeds.", "Roasted and sold in paper twists at every market of the dry south. Caravans carry it because it does not spoil."),
            V("common bean", "A bean of warm lands, bushy or climbing up poles and maize stalks, with long pods of kidney-shaped seeds in many colours.", "Planted with maize and squash as three sisters: the maize holds the bean up, and the bean feeds the soil."),
            V("cowpea", "A trailing bean of hot dry land with long thin pods and small pale seeds with a black eye.", "The Sunlanders eat the black-eyed bean at the new year, for luck, and plant it between the millet."),
            V("cabbage and kale", "Leafy plants of cool gardens: round heads of cabbage and tall curled kale, blue-green and standing through the winter.", "The winter green of the north. Northmen ferment it in barrels and take it to sea against the sailors' sickness."),
            V("onion and alliums", "Onions, leeks and garlic in neat garden rows: hollow green leaves above, bulbs below, hung in plaits to dry.", "Garlic keeps off the evil eye and things that walk at night. The builders of the Old Realms were paid in onions."),
            V("carrot and root vegetables", "Carrots, turnips, parsnips and beets: roots of white, purple, yellow and red, pulled from garden beds and kept in sand through the winter.", "The turnip is the food of honest poverty in every tale. Halflings grow them to a size that wins prizes."),
            V("melons", "Trailing vines on warm sandy soil and river banks, with melons, gourds and watermelons lying heavy on the ground.", "The Saltroad folk count a slice of melon in the desert among the proofs of a kind god."),
            V("enset", "A plant like a giant banana grown round highland houses in the tropics. It bears no fruit worth eating: the pulp of its stem and root is buried to ferment and baked as bread.", "A highland house with enset round it has never known famine. It is called the tree against hunger."),
        ], "The food of garden and field that is not grain: roots, tubers, beans, peas and greens, grown in plots near the house and carried to market in baskets.", "What kept the poor alive when the grain failed. Halflings came through the Ashen Years on their cellars of roots and beans, and shared them."),
        R(Resource.Orchard, "Orchard",
        [
            V("olive", "A grey-green, twisted tree of dry sunny hills that lives for centuries. Its small bitter fruits are pressed for oil.", "The oil lights the lamps, anoints kings and feeds the poor. A branch of it means peace in every land that grows it."),
            V("grape", "Vines trained on stakes, trees or trellises on sunny slopes, with broad lobed leaves and hanging bunches of green or purple grapes.", "Wine is the blood of the god in half the temples. Elves keep vintages older than the kingdoms that buy them."),
            V("date palm", "A tall palm of desert oases, with its foot in water and its head in fire. Heavy clusters of brown, sweet dates hang under the crown.", "The Saltroad folk greet a guest with dates and milk. They say the palm was made from what was left of the clay of the first man."),
            V("fig", "A low, spreading tree of warm dry land, with smooth grey bark and large lobed leaves. The soft purple or green fruits are dried on mats.", "To sit under one's own vine and fig tree is the whole of peace. The tree is never seen to flower, and people wonder at it."),
            V("pomegranate", "A thorny shrub or small tree with scarlet flowers. Its round, leathery red fruit is crowned like a small king and full of juicy red seeds.", "The fruit of the dead and of marriage. Six seeds of it kept a goddess underground for half the year."),
            V("almond", "A small tree of dry hills that blossoms pink and white before any other. The nuts lie in a hard pitted shell inside a grey-green velvet hull.", "The first blossom of the year, and so the tree of watchfulness. Sugared almonds are given at weddings."),
            V("pistachio", "A small, tough tree of hot dry hills, with clusters of reddish fruit whose shells split open on a green kernel.", "Lovers meet under the trees at night to hear the shells crack open, which is good luck."),
            V("apple", "A round-headed tree of cool lands, with pink-white blossom in spring and red, green or yellow apples in autumn.", "Every forbidden fruit and every prize of beauty is an apple in the telling. Halflings wassail the trees in midwinter."),
            V("pear", "A tall, upright tree of cool lands with white blossom and green or russet pears. It lives longer than the apple.", "Plant pears for your heirs, the saying goes. Perry is the drink of the western Midlander shires."),
            V("peach and stone fruit", "Small trees of warm sheltered gardens: peach, apricot, plum and cherry, with pink and white blossom and soft fruit around a stone.", "The Canal folk hold the peach to be the fruit of long life, and paint it on the birthday gifts of the old."),
            V("citrus", "Evergreen trees with dark glossy leaves, scented white flowers and bright fruit: oranges, lemons and citrons, grown in walled, watered gardens.", "A golden fruit in a walled garden is a king's boast. Sailors have learnt to carry lemons, and not why."),
            V("walnut", "A large spreading tree with smooth grey bark. The nut ripens in a green husk that stains the hands brown.", "Nothing grows in its shade. The nut is shaped like a brain, so it is prescribed for the head."),
            V("sweet chestnut", "A large tree of warm hill country with long toothed leaves. The brown nuts ripen in prickly green burrs and are the bread of the mountains.", "Hill people who have never seen a wheat field live on its flour. The lowlanders call them chestnut eaters, and mean it badly."),
            V("hazel", "A shrub of many stems in woods and hedges, with yellow catkins in late winter and small round nuts in leafy cups.", "The tree of wisdom and of the dowser's rod. A good nut year is a good year for babies, the Midlanders say."),
            V("coconut", "A tall leaning palm of tropical shores, with a crown of feathered fronds and clusters of large green and brown nuts.", "The Shoalfolk call it the tree of a hundred uses and plant one for each child. A drifting nut founds an island."),
            V("oil palm", "A stout palm of wet tropical land, with dense bunches of orange-red fruit at the base of the fronds. The fruit is boiled for a red oil.", "The red oil is in every Sunlander pot, and its wine in every cup. The tapper climbs with a rope round the trunk and his waist."),
            V("mango", "A great, dense, dark-leaved shade tree of the tropics, hung in season with oval green, yellow and red fruit on long stalks.", "Rainkeeper villages meet under the mango tree. Its leaves are hung over the door for a wedding."),
            V("cashew", "A low, spreading tropical tree. Each nut hangs in a grey kidney-shaped shell under a swollen red or yellow false fruit.", "The shell burns the hands that crack it. The work is given to those who have no other."),
            V("shea", "A gnarled tree of the dry savanna, left standing in the fields. Its plum-like green fruit holds a nut that is boiled and churned to a pale butter.", "The butter is women's gold among the Sunlanders: gathered, churned and sold by women, and the men have no say in the money."),
            V("baobab", "A savanna tree with a vast, swollen grey trunk and short bare branches like roots in the air. Its velvety pods hold a sour white pulp.", "A god pulled it up and planted it upside down, in anger. Sunlanders bury their praise-singers in its hollow trunk."),
            V("tamarind", "A big tropical shade tree with feathery leaves and brown, brittle pods filled with a sticky, sour-sweet pulp.", "Spirits live in it, and no one sleeps under one. Its pulp polishes brass and sours every dish of the monsoon lands."),
            V("breadfruit", "A tall tree of tropical islands with large, deeply cut glossy leaves and round green fruit the size of a head, baked like bread.", "One tree feeds a household for life, and so the islanders have time to sing."),
            V("Brazil nut", "A giant of the rain forest, far taller than the trees around it. Its fruit is a woody ball like a cannonball, packed with three-sided nuts.", "It cannot be planted in an orchard: it fruits only in the deep forest. The Boughwalkers gather it, and stand clear when the balls fall."),
            V("avocado", "A leafy tree of warm highlands with pear-shaped, dark green fruit: buttery flesh around one large stone.", "The highland peoples call it by the word for a part of a man, and keep girls indoors at the harvest."),
            V("sunflower", "A field crop taller than a person, with one great yellow flower head that follows the sun. The seeds are pressed for oil.", "It turns its face to the sun all day. The Noonfolk plant it at their doors as a kindred thing."),
            V("rapeseed", "A field crop of cool lands that flowers in sheets of bright yellow in spring. Its small black seeds are pressed for lamp oil.", "Its oil lights the lamps of the north where the olive will not grow. It smokes, and the north is used to that."),
            V("sesame", "An upright plant of hot dry fields with pale bell flowers and seed capsules that burst open when ripe. The tiny seeds give a fine oil.", "The pods open at a touch, and so a door in a tale opens at its name. The oil does not go rancid on a long road."),
            V("groundnut", "A low plant of warm sandy soil whose flowers bend down and push into the ground. The nuts ripen there, in pale wrinkled pods.", "It hides its fruit in the earth. The Sunlanders grind it into a stew, and travellers ask for it by name."),
            V("soybean", "A bushy, hairy bean plant of warm temperate fields, with short pods of round yellow beans, pressed for oil and made into curd and sauce.", "The Canal folk make of it a milk, a curd and a black sauce, and call it the meat of the fields."),
        ], "Trees, vines and oil plants that stand for years: orchards, vineyards, groves and nut woods, grown for fruit, nuts, oil and wine and sold more than eaten at home.", "A tree planted is a claim on the land for a lifetime. Armies cut orchards down to punish a people for a generation, and every law calls it a crime."),
        R(Resource.Livestock, "Livestock",
        [
            V("yak", "A shaggy, long-haired ox of high cold plateaus, black or brown, with wide horns and a bushy tail. It gives milk, wool, meat and dung for the fire.", "Hearthbloods live on its butter, stirred into salt tea, and burn its dung. A herd is a hall's whole wealth."),
            V("goats", "Lean, agile animals with horns and beards, in every colour, that browse thorn and rock where nothing else can live.", "The poor man's cow. Dwarves keep them on the high pastures above the hold, and the goat is the devil's beast in the lowlands."),
            V("alpine summer pasture", "High green meadows above the tree line, grazed by cattle and sheep in the summer months only, with stone huts where the cheese is made.", "The herds go up with bells and garlands in spring and come down with the cheese in autumn. The right to the high grass is the oldest law of a valley."),
            V("herded reindeer", "Half-tame reindeer kept in great herds on tundra and in northern forest, followed by their herders through the year.", "The herd is the people. A child is given a calf at birth, and its descendants are the child's dowry."),
            V("sheep", "Woolly flocks, white, grey and black, on hill pasture, heath and stubble. Kept for wool first, and for milk and mutton.", "Wool built the Midlander towns, and the great lords evict their tenants to make room for it. The sheep, it is said, eat men."),
            V("cattle", "Horned cows and oxen, red, black and dun, smaller than modern beasts. They pull the plough and give milk, meat and hides.", "Sunlanders count wealth, marriage and blood-price in cattle. The old epics of every people are about a cattle raid."),
            V("pigs", "Lean, bristly, long-snouted pigs, dark and half wild, that feed in the woods on acorns and beechnuts and in the streets on refuse.", "The peasant's meat, killed at the first frost and salted for the winter. Some faiths forbid it, and are known by that."),
            V("water buffalo", "A heavy, dark grey beast with wide swept-back horns that wallows in mud and pulls the plough through flooded rice fields.", "The tractor of the paddy. Canal folk children ride it home in the evening, and a family that loses it sells a field."),
            V("poultry", "Hens, ducks and geese that scratch about the yard and the pond, kept for eggs, meat and feathers.", "The hen is the wife's, and the egg money with it. A cock crows on the temple tower against the dark."),
        ], "The animals kept for meat, milk, wool and hides: herds and flocks on pasture, moor and stubble, with their herders and dogs.", "Wealth that walks: the oldest word for money is the word for cattle. Herders and farmers have been at law over trampled corn since the Dawn."),
        R(Resource.Fish, "Fish",
        [
            V("cod banks", "Shallow banks in cold seas where great grey-green cod gather in their thousands. They are caught on long lines and dried on racks until hard as wood.", "The Northmen found the banks and told no one for a century. Dried cod is the only coin some coasts have ever used."),
            V("herring", "Vast silver shoals of small fish in cold seas, netted from fleets of open boats and packed in barrels of salt.", "The silver of the sea. Whole leagues of towns have risen on the shoals, and fallen when the shoals moved away."),
            V("sardine and anchovy", "Small silver fish of warm seas that shoal near the surface, netted at night by the light of torches.", "The Old Realms rotted them into a sauce and shipped it in jars to every province. The shards still smell."),
            V("reef fish and shellfish", "Bright-coloured fish, clams and conches from coral reefs and warm lagoons, taken with spears, traps and by hand.", "The reef is the Shoalfolk's field, parcelled by family. A reef may be closed for a season by planting a marked pole on it."),
            V("tuna and large pelagics", "Great, fast, blue-backed fish of the open sea, as heavy as a person, taken in trap nets on their yearly run past the headlands.", "A whole village rows out for the kill and the sea turns red. The chief of the trap is called by a king's title."),
            V("crabs, lobsters and shrimp", "Armoured, clawed creatures of rocky and muddy shores, caught in baited wicker pots and push nets.", "Fed to servants and prisoners on the cold coasts, who have it written into their terms that it shall not be every day."),
            V("salmon runs", "Big silver fish that swim up cold rivers from the sea each year and leap the falls. They are speared and trapped at weirs.", "The salmon of knowledge swims in every tale of the west. The first fish of the run is put back, with thanks."),
            V("oysters and mussels", "Beds of shellfish on rocks and mud flats between the tides: rough grey oysters and blue-black mussels, gathered at low water.", "The food of the poor, eaten by the hundred. The shell heaps behind the Shoalfolk villages are hills."),
            V("sturgeon", "A huge, ancient river fish, longer than a person, with a long snout and rows of bony plates. Its meat and its black roe go to lords' tables.", "A royal fish: wherever it is caught it belongs to the ruler. Its roe is salted for courts, and the fishers eat the rest."),
            V("river fish", "Pike, carp, perch and bream of slow rivers, taken with nets, traps and weirs, and kept alive in ponds.", "The monks keep carp ponds for the fast days. The pike in the pond is said to be as old as the abbey."),
            V("eels", "Long, slippery, snake-like fish of rivers and marshes, trapped in wicker pots at mills and weirs and smoked or salted.", "No one has seen an eel's eggs. The learned say they are born of mud, and the trappers let them say it."),
            V("lake fish", "Trout, whitefish and perch of clear lakes, netted from small boats and through holes in the ice in winter.", "The Hoarkin and the Northmen fish through the ice in winter. A hole is owned for the season, and marked with a branch."),
        ], "The catch of sea, river and lake: fish and shellfish taken with net, line, trap and spear, and eaten fresh, salted, smoked or dried.", "The food of fast days and of the poor of every coast. A catch spoils in a day, so the salter grows rich on the fisher's luck."),
        R(Resource.WildFoodAndGame, "Wild food & game",
        [
            V("edible seaweed and kelp", "Brown, red and green weed gathered from the rocks at low tide and dried on the shore, for food, for fodder and for the fields.", "Famine food on the Northern coasts, and daily food on the eastern ones. The Shoalfolk grow it on ropes."),
            V("wild sheep and ibex", "Sure-footed mountain animals with great curved horns that keep to cliffs and high ledges. Hunted for meat, hide and horn.", "The stones in an ibex's stomach are sold against poison. Hearthblood boys must bring one down alone to be counted as men."),
            V("waterfowl", "Ducks, geese and swans that gather on marshes, lakes and river mouths in great noisy flocks, taken with nets and decoys.", "The geese go over in autumn and the north reads the winter from how high they fly. The swan is the lord's alone."),
            V("lotus", "A water plant of warm ponds and slow rivers with round leaves and large pink flowers held above the water. Its seeds and long roots are eaten.", "It rises clean from the mud, and the Rainkeepers set their gods upon it. Those who eat the fruit in the tales forget their homes."),
            V("seals", "Sleek, grey, spotted sea animals that lie on rocks and ice at the shore. Hunted for meat, blubber and oil.", "The Hoarkin live on the seal: meat, oil for the lamp and a skin for the boat. The seal people of the tales shed that skin on the shore."),
            V("caribou", "Wild reindeer that cross tundra and northern forest in herds of thousands. They are hunted at river crossings.", "The herds cross where they have always crossed, and the hunters wait there. In the year they do not come, the people starve."),
            V("cloudberry and crowberry", "Low plants of bog and tundra: the cloudberry with one amber berry on a stalk, the crowberry a mat with small black ones.", "The gold of the bogs. Northmen have a law on cloudberries, and the picking places are a family secret."),
            V("deer and elk", "The big game of northern forests: red deer with branching antlers and the tall, long-legged elk with its broad shovels.", "The Northmen hunt the elk on skis in the deep snow. Its hoof is carried against the falling sickness."),
            V("bilberry and blueberry", "Low shrubs that carpet the floor of pine and birch woods, covered in late summer with small blue-black berries that stain the mouth.", "A blue mouth gives away the child who was sent for a full basket. The berries are the right of all in the northern woods."),
            V("forest mushrooms", "The mushrooms of the forest floor in autumn: brown ceps, yellow chanterelles and many more, gathered into baskets and dried on strings.", "Each family has its places and does not share them. Bitterbloods are asked to the first meal of the season, to eat first."),
            V("deer", "Red, fallow and roe deer of woods and their edges: the lord's game and the poacher's.", "The lord's game. A hart with a cross between its antlers has converted more than one huntsman in the legends."),
            V("wild boar", "A dark, bristly wild pig with tusks that roots in oak and beech woods. A dangerous quarry, hunted with spear and hounds.", "The beast of the midwinter feast, carried in with an apple in its mouth. A boar's tusks on a helmet are an Orc chief's mark."),
            V("acorns", "The nuts of the oak, in their small cups, that cover the wood floor in autumn. Pigs are fattened on them, and people eat them leached in hungry years.", "The right to fatten pigs on them is counted in the lord's rolls. The Orcs grind and eat them, and outlasted the Ashen Years on it."),
            V("raspberry and bramble", "Thorny, arching canes at wood edges and in clearings, with red raspberries and black bramble berries.", "Brambles are not picked after the first frost: the devil has spat on them. They are the fruit of everyone who has no garden."),
            V("bison and wild cattle", "Huge, shaggy, humped wild oxen of grassland and open forest, in herds that shake the ground.", "The Grass riders drove them over cliffs before they had horses. A horn of the great wild ox is a king's drinking cup."),
            V("hares and rabbits", "Long-eared grazers of field and heath: the hare alone in the open, rabbits in warrens of burrows. Snared and coursed with dogs.", "Witches go about as hares, and a hare crossing the road turns a traveller back. The warren is the lord's, and the rabbit the poacher's."),
            V("antelope and gazelle", "Slender, swift, horned grazers of dry plains, fawn and white, in leaping herds.", "The Saltroad poets compare every beloved to a gazelle. It is hunted with hawks and swift hounds, from horseback."),
            V("upland game birds", "Grouse, partridge, pheasant and quail of moor, heath and field edge, taken with nets, snares and hawks.", "Quail fall on the desert in their thousands, tired from the crossing, and are taken by hand. A partridge is a lord's dish."),
            V("wild herbs", "The green herbs of the kitchen that grow wild: garlic leaf, sorrel, nettle, mint and cress, gathered in spring.", "The first green of spring, after a winter of salt meat. Nine herbs go into the pot on the first warm day."),
        ], "What the wild land gives without sowing: game, wildfowl, berries, nuts, mushrooms and herbs, taken by hunters and foragers.", "Free to all in the old law, and the lord's in the new. The forest feeds a village in a bad year, and hangs a man for it in a good one."),
        R(Resource.Timber, "Timber",
        [
            V("larch", "A conifer of cold mountains and the far north that sheds its soft needles gold in autumn. Its hard, reddish wood resists rot.", "A city of the lagoons stands on larch piles driven into the mud, and they have not rotted in a thousand years."),
            V("spruce", "A dark, spire-shaped conifer with drooping boughs and long hanging cones, in dense northern forests. Light, straight wood for masts, boards and instruments.", "Gnomes buy the slow-grown spruce of the high valleys for the bellies of their instruments, and tap each trunk to hear it first."),
            V("Scots pine", "A tall pine with orange-red upper bark and a flat blue-green crown, on sand and rock. It gives straight timber, tar and pitch.", "The Northmen's tree: it gives the mast, the plank and the tar. A lone pine marks a grave or a meeting place."),
            V("fir", "A tall, regular conifer of mountain forests, with flat needles, silver below, and cones that stand upright. Long beams for roofs.", "The ridge beam of a great hall is one fir, drawn from the mountain by forty oxen. A small one is brought indoors at midwinter."),
            V("beech", "A tall tree with a smooth grey trunk like a pillar and a dense canopy that shades the ground bare. Pale hard wood for tools, furniture and fuel.", "The first books were beech boards, and the word for a book is the word for the tree. Its mast fattens the pigs."),
            V("oak", "A massive, broad-crowned tree with a rugged trunk and lobed leaves. The strongest and most lasting timber, for ships, frames and barrels.", "The Old Realms planted oaks in rows for ships they never built. Lightning seeks it, and so it is the thunder god's."),
            V("lime", "A tall tree with heart-shaped leaves and sweet-scented flowers. Its soft pale wood is the carver's, and its inner bark makes rope.", "The village court sits under the lime tree, since no one can lie in its shade. Every holy image of the north is carved from it."),
            V("cedar", "A great mountain conifer with wide, flat tiers of dark branches. The red, scented wood does not rot and roofs temples and palaces.", "Kings have sent armies for it since the Dawn, and the mountains where it grew are bare. What stands is guarded by priests."),
            V("ash", "A tall, open tree with feathered leaves and black winter buds. Tough, springy pale wood for spear shafts, handles and wheels.", "The world hangs on an ash tree in the Northmen's telling. Every spear and every axe handle is cut from it."),
            V("elm", "A tall tree of valleys and hedgerows with a lopsided leaf. Its wood does not split and lasts under water: wheel hubs, pipes and piles.", "The coffin tree, and the water pipe under the street. It drops a bough without warning, and is not trusted."),
            V("giant conifers", "Trees of the wet western coasts, taller than any tower, with red, fibrous trunks wider than a house and no branch for the first fifty paces.", "One tree builds a village. The Amberbloods say the oldest of them were people once, and can name some."),
            V("juniper", "A small, twisted evergreen of dry slopes, with blue berries and prickly needles. Scented red wood for posts, chests and smoking meat.", "Burnt at the turn of the year to smoke out sickness and spirits. Its berries go into the strong drink of the north."),
            V("cypress", "A narrow, dark, flame-shaped evergreen of warm dry lands. Scented, lasting wood for doors, chests and coffins.", "Planted on graves in the south, since it never sprouts again once cut. Temple doors of it have lasted eleven centuries."),
            V("Mediterranean pines", "Pines of warm coasts: umbrella-shaped stone pines and wind-leaning coast pines, on red earth above a blue sea. Ship timber, resin and pine nuts.", "The pine cone is the sign of the wine god and tops his staff. Resin from these trees flavours the wine and seals the jars."),
            V("cork oak", "An evergreen oak of warm dry hills. Its thick, spongy bark is stripped every ten years and leaves the trunk red-brown.", "The tree may be stripped once in nine years, and the year is painted on the trunk. To strip it sooner is theft from one's own son."),
            V("teak", "A tall tree of the monsoon forest with huge rough leaves that fall in the dry season. Its golden-brown, oily wood is the best there is for ships.", "The Rainkeepers haul it with elephants and float it for two years to the sea. A teak ship outlives three of oak."),
            V("sal", "A tall, straight tree that stands in pure forests in the monsoon lands. Hard, heavy brown wood for beams and posts, and a resin burnt as incense.", "The Rainkeepers hold it holy: a teacher of theirs was born under one and died between two."),
            V("Spanish cedar", "A tall tree of the tropical forest with light, red-brown, scented wood that insects leave alone. Easy to work, for chests and boats.", "Chests of it keep moths from cloth, and the scent tells a buyer the wood is true."),
            V("rosewood", "A tropical tree with dark wood streaked purple and black that smells of roses when cut. For fine furniture and instruments.", "Court furniture and the finest instruments. Its export is the ruler's alone, and a log of it is weighed like spice."),
            V("mahogany", "A giant of the tropical forest with a buttressed trunk. Its red-brown wood works smooth and takes a deep polish.", "One tree is worth a house, so the cutters search the forest for a year to find it."),
            V("iroko", "A great tree of the tropical forest and its edge, with golden wood that darkens to brown and resists rot and insects.", "A spirit lives in it, and a Sunlander woodcutter asks its leave. Furniture made of it is heard to groan at night."),
            V("ebony", "A small tree of dry tropical forest whose heartwood is jet black and so heavy that it sinks in water.", "Sold by weight, like metal. Black thrones and the black keys of instruments, and it turns a poisoned cup, they say."),
            V("African mahogany", "A tall tree of the wet tropical forest and river banks, with pinkish wood that darkens to red-brown. Canoes are hollowed from single trunks.", "The Sunlanders hollow war canoes for sixty paddlers from one trunk, and carve the prow before the tree is dry."),
            V("thorn-scrub wood", "Small, hard, crooked thorn trees with flat crowns, in dry bush. Wood for posts, fences, tool handles and charcoal.", "The cattle fold of every dry country is a ring of cut thorn. The wood is so hard that it is shaped green or not at all."),
            V("mangrove timber", "Trees that stand on stilt roots in tidal mud. Dense red wood that does not rot in salt water: poles, piles and a bark for tanning.", "The Shoalfolk build on mangrove stilts that outlast the house. The poles are shipped to the treeless coasts as rafters."),
            V("poplar", "A fast, tall, straight tree along rivers and the canals of dry lands. Light, soft wood for roof poles and boards.", "The Saltroad folk plant a row at a son's birth, to be the roof beams of his house."),
            V("willow and poplar", "The trees of river banks and wet meadows: pollarded willows with a head of shoots for baskets and hurdles, and poplars for light boards.", "The willow weeps, and is the tree of the forsaken. Cut back every few years, it gives the baskets of the whole country."),
            V("driftwood", "Bleached logs thrown up by the sea on treeless northern coasts: the only timber there is, grey-white and smooth.", "The Hoarkin own no tree, and hold that the sea sends each log to someone. The finder marks it, and no one touches it."),
        ], "Wood for building, ships, tools and fuel: standing forest and the logs taken from it, felled with the axe and hauled by ox and river.", "The Old Realms cut forests for fleets and furnaces, and the Elves have not forgiven it. Every people has a law on which tree may fall, and breaks it for a ship."),
        R(Resource.Stone, "Stone",
        [
            V("granite", "A hard, speckled stone, grey or pink, with glittering grains. It lies in rounded tors and great blocks, is slow to cut and lasts for ever.", "Dwarves cut their halls in it and call the softer stones summer rock. A granite cross outlasts the faith that raised it."),
            V("slate", "A fine, dark, blue-grey stone that splits into thin flat sheets, quarried from hillsides for roofs and floors.", "A roof of it lasts a century, and the schoolchild writes on a piece of it. The slate valleys speak a tongue of their own."),
            V("marble", "A white or veined stone that takes a polish and glows in the light, cut in great blocks from mountain quarries for temples and statues.", "The Old Realms faced whole cities with it. Later peoples burnt the statues for lime, and build their walls from the temples."),
            V("whetstone", "A fine, gritty, grey stone cut into bars for sharpening blades. A good quarry is known across many lands.", "The Northmen traded whetstones across the sea, and a king was buried with one as a sceptre. A reaper is no better than his stone."),
            V("basalt", "A dark, heavy, fine-grained stone of old lava, often standing in six-sided columns. For walls, paving and querns.", "The six-sided columns are a road built by giants, as anyone living near them will explain."),
            V("pumice and pozzolana", "The light stuff of volcanoes: grey pumice full of holes, which floats on water, and a fine ash that makes mortar set under water.", "The harbour moles of the Old Realms were poured with this ash and have stood in the sea ever since. No one now knows the mixture."),
            V("obsidian", "Black volcanic glass that breaks with a curved, shining face and an edge sharper than steel. For blades, mirrors and ornaments.", "Seers look into a polished mirror of it. A blade of it cuts cleaner than steel, and the Flinchless surgeons keep one."),
            V("millstone and quern stone", "A hard, rough, gritty rock that keeps its bite. Cut into round stones for mills and hand querns.", "The lord breaks the hand querns of his tenants, so that they must pay at his mill. Old ones are found buried under floors."),
            V("soapstone", "A soft, grey-green stone that feels greasy and can be cut with a knife. It does not crack in fire: pots, lamps and moulds.", "The Hoarkin carve their blubber lamps of it. A pot of it holds its heat for an hour off the fire."),
            V("chalk", "A soft, white stone that lies in rolling downs and shows in white sea cliffs. Burnt for lime, and cut for inner walls.", "Giants and white horses are cut into the chalk hills, and scoured every seven years with a fair. No one knows who cut the first."),
            V("limestone", "A pale grey or cream stone in level beds, easy to cut and carve. The common stone of walls, towers and temples, and burnt for lime.", "The stone of the great temples, soft from the quarry and hard in the air. It is full of shells from a sea no one remembers."),
            V("flint and chert", "Hard, glassy nodules, grey and black inside a white rind, found in chalk. Knapped to a sharp edge, struck for fire, and set in walls.", "The thunderstones turned up by the plough are flint arrowheads from the Dawn. They are kept under the roof against lightning."),
            V("sandstone", "A stone of bound sand, in red, yellow, brown and grey, that cuts freely into blocks and weathers into ledges and cliffs.", "Whole cities of the dry lands are cut into red cliffs of it: tombs, temples and cisterns, with no stone laid on another."),
            V("field stone and boulders", "Loose stones and rounded boulders cleared from the fields and stream beds, piled into dry walls and rough foundations.", "The fields grow stones, the farmers say: a new crop every spring. The walls are the work of thirty generations."),
            V("gypsum and alabaster", "A soft, white stone: gypsum, burnt for plaster, and its fine, translucent form, alabaster, carved into figures and thin window panes.", "The effigies on the tombs of lords are alabaster, and so are the lamps of the Saltroad temples, which glow through the stone."),
        ], "Stone to build and carve with, broken from quarries and cliffs or gathered from the fields: grey, white, red or black, by the rock under the land.", "Wood is for the living and stone for the gods, the dead and the lord. A city is the colour of its nearest quarry."),
        R(Resource.Clay, "Clay",
        [
            V("adobe and mud-brick earth", "Earth of dry lands mixed with straw and water, shaped in moulds and dried in the sun into pale brown bricks.", "A mud town is rebuilt on its own ruins until it stands on a hill of them. The Saltroad folk replaster the temple each year as a festival."),
            V("brick and pottery clay", "Sticky grey, red or yellow clay dug from pits in river valleys, that fires hard and red in the kiln.", "The Old Realms stamped each brick with the name of the ruler. The bricks are still in use, in other people's walls."),
            V("wattle and daub", "Clay mixed with straw and dung and smeared over a weave of hazel rods between the timbers of a house.", "A house a family can build in a week with what lies within a mile. Daubing day ends with a dance on the floor to tread it flat."),
            V("rammed earth and cob", "Damp earth with gravel and straw, rammed between boards or built up by hand into thick walls with rounded corners.", "The long walls of the Canal folk are rammed earth. A cob house wants a good hat and good boots, the builders say: a roof and a stone footing."),
            V("kaolin", "A pure, white, soft clay from rotted granite that fires white and fine: the earth of the best ware.", "The white ware of the Canal folk is made from it, and for centuries no one else knew how. It is named for a hill of theirs."),
        ], "Earth that can be shaped: clay for pots, bricks and tiles, and loam for the walls of houses, dug from pits on low ground.", "The first people were made of it, in most tellings. A potter's shards outlast the kingdom that used the pots."),
        R(Resource.Crystal, "Crystal",
        [
            V("rock crystal", "Clear, six-sided spears of quartz, like ice that does not melt, found in clefts of high rock. Cut for lenses, vessels and jewels.", "Held to be ice frozen so hard that it cannot melt. A ball of it is the seer's glass, and a king's sceptre is tipped with it."),
            V("glass sand", "Fine, white sand, free of iron, from beaches, dunes and river bars. Melted with ash or soda into glass.", "Glass was found, the story goes, by sailors who propped their cooking pot on blocks of soda on a beach. The Brinefolk tell it of themselves."),
        ], "The clear stuff of glass and lenses: rock crystal from the mountains and pure white sand from shores and rivers.", "Clear things hold light, and what holds light may hold more. Mages, glassmakers and Gnomes pay for the same sand and the same stones."),
        R(Resource.Fibre, "Fibre",
        [
            V("flax", "A slender, knee-high plant with sky-blue flowers, grown in cool damp fields. Its stems are soaked, beaten and combed to pale fibre for linen.", "The priests of the old temples wore nothing but linen. Northmen bury a woman with her flax comb."),
            V("hemp", "A plant taller than a person with jagged, hand-shaped leaves. Its coarse, strong fibre goes to rope, sailcloth and sacks.", "The rope of every ship and every gallows. The Grass riders throw its seed on hot stones in a closed tent, and howl with pleasure."),
            V("cotton", "A bushy plant of hot lands with yellow flowers and pods that burst into balls of white fluff, picked by hand.", "The first travellers said it was the wool of a lamb that grew on a stalk. The Rainkeepers weave it so fine that a length passes through a ring."),
            V("jute", "A reed-like plant twice the height of a person, grown in hot, flooded river plains. A golden-brown fibre for sacks and cord.", "The golden fibre of the delta. Every sack on every quay is made of it, and the sack is worth nothing, so no one steals it."),
            V("ramie", "A tall nettle without stings from warm wet lands. A white, lustrous fibre, stronger than flax, for fine cloth.", "The Canal folk wrap their dead in it and wear it in summer. It is whiter and older than their silk."),
            V("kenaf", "A tall, cane-like plant of hot lands, with hollyhock flowers and a coarse fibre like jute.", "Ropes, sacks and the caulking of boats in the hot lands. The Sunlanders eat its leaves and twist its bark."),
            V("sisal and agave", "Rosettes of stiff, sword-shaped, spine-tipped leaves on dry ground. The leaves are scraped for a hard, pale fibre for rope.", "The plant flowers once, after many years, and dies. The highland peoples brew its sap and say a goddess lives in it."),
            V("abaca", "A plant like a banana, of wet tropical islands. The fibre of its leaf stalks makes ship's rope that does not rot in sea water.", "The Shoalfolk moor their houses with it. Northmen captains who have used it once will pay any price for a second cable."),
            V("esparto grass", "A tough, wiry grass that grows in grey tussocks on dry hills. Plaited into rope, baskets, mats and sandals.", "The miners of the dry hills wear sandals of it and carry ore in baskets of it. A pair lasts a week."),
            V("silk", "The thread of the silkworm, a pale caterpillar fed on mulberry leaves in trays indoors. The cocoons are white and gold, the thread fine and shining.", "A princess of the Canal folk carried the eggs out in her headdress, and the secret with them. The road it is traded along is named for it."),
            V("kapok", "A giant tropical tree with a spiny trunk and great buttresses. Its pods are stuffed with a silky floss, for pillows and padding.", "The tree joins the earth to the sky, in the forest peoples' telling. The Boughwalkers build in its crown."),
            V("New Zealand flax", "A plant of wet ground on far southern coasts, with stiff, sword-shaped leaves as tall as a person, scraped for a strong fibre.", "The cloaks woven of it show a wearer's rank by their border. The plant is cut so that the child leaf and its parents are left."),
            V("nettle and lime-bast", "The poor land's fibres: thread from the stems of stinging nettles and cord from the inner bark of the lime tree.", "Shirts of nettle are worn where flax fails. A sister in the tale weaves seven of them in silence to free her brothers."),
        ], "Plants and threads that are spun and twisted: fibre for cloth, rope, sacks and nets, grown in fields or gathered wild.", "A people is clothed in what grows near it, and the rich in what does not. The spindle is in every woman's hand from the Dawn onward."),
        R(Resource.Fuel, "Fuel",
        [
            V("charcoal", "Black, light, ringing lumps of wood burnt slowly without air in a turf-covered mound in the forest. The fuel of the smith and the smelter.", "Without the charcoal burner no iron is made. A forge town counts its forest in years of charcoal left."),
            V("firewood", "Split logs and bundled faggots from coppice and forest, stacked to dry against the wall of every house.", "A villager may take dead wood by hook or by crook, and no more. A winter is measured in cords."),
            V("peat", "Dark brown, fibrous earth cut in bricks from bogs and stacked to dry. It burns slowly, with a thick sweet smoke.", "The fire of a peat house is never let out: it is carried from the mother's hearth to the bride's. It gives the northern drink its taste."),
            V("turf and sod", "Slabs of grass and roots cut from heath and moor, dried and burnt where there is neither wood nor peat.", "The Northmen build with it as well as burn it: a hall of turf is green in summer and grazed by the goat."),
            V("dung fuel", "Cakes of dried animal dung, slapped on walls to dry and stacked in heaps. The fire of treeless plains.", "Gathering it is the work of the daughters of the Grass riders. The stack beside the tent is the measure of a careful house."),
            V("coal", "Black, shining stone that burns, dug from seams in hillsides and shallow pits. A hot fire with a foul smoke.", "Sea coal, washed out of the cliffs. Smiths wanted it and the towns banned its smoke, and the Dwarves burnt it all along."),
            V("lignite", "Brown, crumbly, woody coal from shallow pits in low ground. A smoky, weak fire.", "The poor man's coal. A town that burns it can be smelt before it is seen."),
            V("oil and naphtha seeps", "Black, stinking oil that wells from the ground into pools and tar pits, and burns. Skimmed for lamps, caulking and fire weapons.", "Fires that have burnt at the seeps since the Dawn have temples built over them. The fire that burns on water is a state secret of the sea cities."),
        ], "What is burnt for heat and for work: wood, charcoal, peat, dung and coal, stacked at every door and forge.", "A town is as large as the wood within a day's carting. Smelters, salters and glassmakers eat forests, and move on when they are gone."),
        R(Resource.Salt, "Salt",
        [
            V("solar sea salt", "Shallow, banked pans on a flat, hot shore, where sea water dries in the sun to a white crust that is raked into gleaming heaps.", "The grey salt of the pans is for the fish barrels, and the white flower that floats on top is for the table."),
            V("lake and playa salt", "The white, cracked crust of a dried salt lake in the desert, blinding in the sun, cut into slabs and carried off by caravan.", "The Brinefolk say the flats are their sea, asleep. The Saltroad caravans carry the slabs south and trade them weight for weight against gold."),
            V("natron and soda", "A white and grey crust at the edge of desert lakes: a bitter salt for glass, soap, bleaching and the embalming of the dead.", "The Brinefolk embalm with it and blow glass with it. The priests of the old temples washed their mouths with it before they spoke to the god."),
            V("rock salt", "Beds of grey, pink and white salt deep in the ground, cut out in blocks in glittering galleries.", "The miners carve chapels and saints from the salt. A lost wedding ring was found in the first block cut, in the founding tale."),
            V("brine springs", "Springs and wells of salt water inland, whose brine is boiled dry in pans over wood fires. A salt town grows round each.", "The Canal folk drill for brine with bamboo, a thousand paces down, and pay the empire's army out of the salt tax."),
        ], "The one thing every house must buy: white salt from sea pans, desert lakes, mines and brine springs, traded in blocks and sacks.", "Oaths are sworn on it, wages were paid in it, and rulers tax it because no one can do without. The Brinefolk hold the great flats in trust and weep the stuff themselves."),
        R(Resource.IronOre, "Iron ore",
        [
            V("bog iron", "Rusty brown lumps and crusts that form in bogs and wet meadows, dug from under the turf with a spade. Poor ore, found everywhere in the north.", "The bog gives it back: a place dug out can be dug again in a generation. Northmen farmers smelt their own in the autumn."),
            V("lateritic iron and ironstone", "Hard, red-brown, pebbly crust on the red earth of hot lands, broken up and smelted in clay furnaces.", "The ore of the first Sunlander smelters. The old furnace sites are holy, and a smith's family guards each."),
            V("banded iron formation", "Ancient rock in thin stripes of red, black and steel grey: a rich ore that lies in whole ridges.", "Whole mountains of it. The Dwarves say the stripes are the years of the world before anyone counted them."),
            V("magnetite skarn iron", "Heavy, black ore in mountain rock that pulls at iron. The richest ore, mined from veins and pockets.", "A sliver of it, floated, points north. Sailors tell of a mountain of it in the far sea that pulls the nails out of ships."),
            V("black sands", "Heavy, black, glittering sand in streaks on beaches below dark cliffs, gathered and washed for the iron in it.", "The eastern swordsmiths make their best steel from it, washing a hillside into the river for a single blade."),
        ], "The red, brown and black stone that iron is smelted from, dug from bogs, pits and mountain veins.", "The Sunlanders smelted it first. Iron is the metal of the plough and the sword, and things of the old magic are said not to bear its touch."),
        R(Resource.CopperOre, "Copper ore",
        [
            V("porphyry copper", "Speckled mountain rock stained green and rusty at the surface, with fine grains of brassy ore through a whole hillside.", "A whole mountain of poor ore. The Dwarves take a hill down from the top, over ten generations, and call it one working."),
            V("malachite and azurite", "Bright green and deep blue crusts and bands in the rock: copper ore that is also ground for paint and cut for ornament.", "Ground for the green of painted eyes and the blue of painted skies. The miners knew copper by these colours before they knew how to smelt it."),
            V("red-bed copper", "Green and blue stains and nodules in beds of red sandstone and shale. A thin ore that spreads wide.", "The works of the Midlander shale lands made a banking family rich enough to buy an emperor."),
            V("massive-sulfide copper", "Heavy, brassy-yellow bodies of ore in dark green rock, under a cap of rusty red and yellow earth.", "An island of the middle sea gave the metal its name. The red caps of the hills there were mined before the Old Realms."),
            V("native copper", "Pure red metal found as lumps and sheets in dark lava rock, green on the outside. It can be hammered without smelting.", "The lake peoples hammered it cold before anyone had a furnace. A lump too big to move was left with offerings on it."),
        ], "Green-stained rock and brassy ore that copper is smelted from, for bronze, brass, pots and coin.", "The metal of the Dawn, before iron. Bronze still makes the bells, the statues and the cauldrons, and the Dwarves count a hold's age by its copper workings."),
        R(Resource.Tin, "Tin",
        [
            V("tin lode", "Veins of heavy, dark brown, shining tin stone in granite, followed underground with pick and fire.", "The mines run out under the sea, and the tinners hear the boulders roll above their heads. They have a parliament and a court of their own."),
            V("stream tin", "Heavy black pebbles and sand of tin stone in the gravel of valley floors below granite hills, washed out with running water.", "The tin islands at the world's edge, which the Old Realms sought and the traders kept off the maps."),
        ], "The rare, heavy, dark stone that white tin is smelted from: the metal that makes copper into bronze, and pewter for the table.", "A little tin makes copper into bronze, and it lies in few places. The Old Realms sent fleets to the edge of the world for it."),
        R(Resource.SilverAndLead, "Silver & lead",
        [
            V("silver", "Veins of dull grey ore, and sometimes wires of the bright metal itself, in mountain rock. Mined deep, by many hands, for coin and plate.", "A mine in the mountains paid for the fleet that saved a city, and another for the ruin of an empire. Silver turns black at poison, they say."),
            V("lead-zinc in carbonates", "Heavy, lead-grey, shining cubes of ore in pockets and veins of limestone hills. Smelted for lead, with a little silver in it.", "The lead of roofs, pipes and coffins. The Old Realms piped their water in it and went mad, the Gnomes maintain."),
            V("calamine", "An earthy, yellow-brown and white ore in limestone, which is heated with copper to make golden brass.", "It turns copper to gold, or near enough for a candlestick. The brass founders long thought it only a dye for the metal."),
            V("lead-zinc skarns and veins", "Veins of grey lead ore and dark, resinous zinc ore in volcanic mountains, with white quartz and a little silver.", "The miners cursed the false ore that would not smelt, and named it for the goblins of the mine."),
        ], "The grey ores of silver and lead, which lie together: silver for coin and plate, lead for roofs, pipes and windows.", "Silver is the coin of every market and the first thing a ruler debases. A silver strike makes a town in a year, and a ghost town in thirty."),
        R(Resource.Gold, "Gold",
        [
            V("lode gold", "Specks and threads of yellow gold in veins of milky white quartz, in old hard rock. Mined, crushed and washed.", "Dwarves follow a quartz vein for generations and record each ounce. Men come for a season and leave their bones."),
            V("epithermal and hot-spring gold-silver", "Rich, banded veins of quartz with gold and silver, in volcanic mountains near hot springs and steaming ground.", "Found where the ground steams. The miners say the fire under the mountain cooks the gold, and hurry."),
            V("placer gold", "Flakes, grains and now and then a nugget of gold in the sand and gravel of rivers, washed out with a pan or a fleece.", "The fleece laid in a stream to catch the dust is the golden fleece of the tale. A Sunlander king's stool is covered in it."),
            V("beach gold", "Fine gold dust in the dark sand of a beach near a river mouth, sorted by the waves and washed out by hand.", "A storm lays it bare and the next one buries it. A whole town can spring up on a beach and be gone in two winters."),
        ], "The yellow metal that does not tarnish, found in white quartz veins and in river sand. Worth more than anything else that is dug.", "It buys kings, and cannot be eaten. The Sunlanders are rich in it, the Saltroad folk carry it, and the Dwarves write down where every ounce went."),
        R(Resource.GemsAndPearls, "Gems & pearls",
        [
            V("pearl oyster", "Rough-shelled oysters on the floor of warm seas, lined with mother-of-pearl. One in many holds a round, lustrous pearl.", "A pearl is a drop of dew or a tear that the oyster swallowed. The Shoalfolk price a reef by its divers' lives."),
            V("precious red coral", "A small, branching, blood-red tree of stone that grows on rock deep under the sea. Polished into beads and charms.", "The blood of a monster's cut head, hardened in the sea. Hung on children against the evil eye, from the middle sea to the high plateaus."),
            V("diamond", "A small, greasy-looking pebble found in river gravels, harder than anything else. Cut, it blazes with white fire.", "It cannot be cut, the old books say, except with a goat's blood. The valley where it lies is guarded by snakes, and reached by throwing meat to the eagles."),
            V("topaz, beryl and tourmaline", "Clear, six-sided crystals in pockets of granite: golden topaz, sea-green beryl, pink and green tourmaline.", "Gnomes ground the first reading lenses from clear beryl, and the word for spectacles remembers it."),
            V("garnet", "Deep red, many-sided crystals the size of a pea or a nut, studded in grey mountain rock.", "The red stones in the sword hilts of the Northmen kings came half across the world. A garnet lights the way of a traveller at night."),
            V("emerald", "A six-sided crystal of deep, clear green, rare and often flawed, in veins of dark mountain rock.", "A serpent that looks on it goes blind. A queen of the south owned the only mines and gave the stones carved with her face."),
            V("amethyst and agate", "The gems of old lava: hollow stones lined with purple amethyst crystals, and agates banded in rings of many colours.", "The amethyst keeps its wearer sober, and so is set in a bishop's ring and a drinking cup."),
            V("ruby and sapphire", "The hardest gems but one: blood-red ruby and deep blue sapphire, found as small barrel-shaped crystals in marble and in the gravels below it.", "Rainkeeper kings take the title lord of the rubies and keep every large stone by law. A sapphire is the stone of an oath."),
            V("jade", "A tough, smooth stone, green to white, found as boulders in mountain rivers. Carved into blades, ornaments and ritual things.", "The Canal folk hold it above gold: it is virtue made visible. A prince is buried in a suit of it, to keep the body whole."),
            V("lapis lazuli", "A deep blue stone flecked with gold, from a few high mountain mines. Cut for inlay and ground for the costliest blue paint.", "It comes from one valley at the roof of the world. The painter's contract says how much of it the patron will pay for."),
            V("turquoise", "An opaque, sky-blue to green stone in thin veins in desert rock, often webbed with brown.", "The Saltroad folk set it on the bridle against a fall. It pales when its owner sickens, and they watch it."),
            V("opal", "A milky stone that flashes with moving fire in every colour as it is turned, in seams in desert sandstone.", "Every stone in one, and so the luck of all of them, or the ill luck. Thieves prize it: it is said to hide the wearer."),
            V("amber", "Golden, clear, warm, light lumps of ancient resin, washed up on cold shores, sometimes with an insect inside.", "The tears of sisters who wept for a brother and became trees. The Amberbloods say it is the blood of their oldest dead, and buy back what they can."),
            V("jet", "A black, light stone of fossil wood from sea cliffs, that polishes to a deep shine. For beads and mourning jewels.", "The stone of mourning. Burnt, it drives off snakes, and it is the one black thing a widow may wear."),
            V("freshwater pearl mussel", "Dark, long-lived mussels in the gravel of cold, clean rivers. One in a thousand holds a small pearl.", "The pearl fishers open a thousand shells for one pearl. The best of a river goes to the crown by old right."),
        ], "Precious stones and the treasures of the sea: gems dug from rock and gravel, pearls and coral brought up by divers. Small, bright and worth a life.", "A fortune that fits in the mouth. Each stone has a virtue in the books, and a history of the hands it was cut from."),
        R(Resource.Spices, "Spices",
        [
            V("black pepper", "A climbing vine of hot wet forest, grown up trees and poles, with hanging strings of green berries that dry black and wrinkled.", "A city was once ransomed for three thousand pounds of it. Rents are paid in peppercorns still, where no one wants them collected."),
            V("clove", "An evergreen tree of small tropical islands. Its pink flower buds are picked before they open and dried to dark brown nails.", "A tree is planted for each child, and the child's fate is read from it. The Canal folk court required a clove in the mouth of anyone who spoke to the emperor."),
            V("nutmeg and mace", "A tropical island tree with a fruit like an apricot, which splits to show a brown nut wrapped in a scarlet lace: the nutmeg and the mace.", "It grows on a handful of islands, and wars have been fought for each of them. Carried in a pocket against the plague."),
            V("cinnamon", "A small evergreen tree of wet tropical land. Its inner bark is peeled and dried into curled, brown, scented quills.", "The spicers said that great birds build their nests of it on cliffs, and it must be brought down with baits of meat. It kept the price up."),
            V("cardamom", "A tall, leafy plant of the forest floor in wet tropical hills. Its small green pods of black, scented seeds grow at the foot of the plant.", "The Saltroad folk put it in the coffee they pour for a guest, and the amount is the measure of the welcome."),
            V("ginger", "A reed-like plant of hot wet land, grown for its knobbly, pale, hot-tasting root.", "A pound of it bought a sheep. Midlander fairs sell it baked into bread in the shape of a man."),
            V("turmeric", "A broad-leaved plant of hot wet land. Its root is bright orange inside and is dried and ground to a yellow powder, spice and dye.", "The Rainkeepers rub a bride yellow with it before the wedding, and tie a root of it round her neck."),
            V("vanilla", "A climbing orchid of wet tropical forest with long green pods, which are cured until black, oily and sweet-scented.", "The flower opens for one morning and must be fertilised by hand. A stolen pod is known by the grower's mark pricked into it."),
            V("chili pepper", "A small bush of warm lands hung with glossy pods, green, red and yellow, that burn the mouth.", "Burnt in the fire, its smoke was a punishment for children and a weapon of war."),
            V("myrrh", "A low, thorny tree of hot, stony desert. Cuts in its bark bleed a red-brown, bitter, scented gum, for incense, medicine and the dead.", "The Brinefolk embalm with it. It is the gift for a death, as frankincense is the gift for a god."),
            V("frankincense", "A small, gnarled tree with papery bark on bare desert cliffs. Its milky sap dries into pale tears that are burnt in temples.", "The trees belong to families and may be cut only by those who are clean. Winged serpents guard them, the Saltroad merchants insist."),
            V("gum arabic", "A thorny acacia of dry savanna. Its bark oozes amber balls of clear gum, for ink, paint, sweets and medicine.", "Every scribe's ink and every illuminator's colour is bound with it. The caravans bring it north in goatskins."),
            V("sandalwood", "A small tree of dry tropical forest that grows on the roots of others. Its yellow heartwood keeps a sweet scent for decades.", "The Rainkeepers burn their dead on it if they can afford to, and mark the forehead with its paste. Every tree belongs to the king."),
            V("rubber latex", "A tall tree of the rain forest that bleeds a white milk when cut. The milk is smoked into dark, springy, waterproof balls.", "The forest peoples make a ball of it for a game that is played for the players' lives. Nobody else has found a use for it."),
        ], "Scented and burning things from hot, far lands: seeds, barks, buds and gums, dried, carried across the world and sold by the ounce.", "The lightest cargo and the dearest. Those who grow them and those who eat them have never met, and the merchants in between mean to keep it so."),
        R(Resource.StimulantsAndSugar, "Stimulants & sugar",
        [
            V("sugar cane", "A giant grass of hot wet land, twice the height of a person, with thick jointed stems full of sweet juice. Crushed and boiled down to brown loaves.", "The reed that gives honey without bees. It came west as a medicine, and the apothecaries sold it by the ounce."),
            V("palm sugar and toddy", "Palms whose cut flower stalks drip sap into pots hung in the crown. The sap is boiled to brown sugar or left to ferment into a milky wine.", "The tapper climbs forty palms twice a day. The sap is sweet at dawn and strong by evening, and no one drinks it at noon."),
            V("tea", "An evergreen shrub of misty, wet hills, kept waist high in rows. The young leaves are picked, rolled and dried.", "A leaf fell into a Canal folk emperor's boiling water. The empire pays for the horses of the Grass riders in bricks of it."),
            V("coffee", "A glossy-leaved shrub of tropical highlands, grown under shade trees, with white flowers and red berries. The two seeds in each are roasted.", "A goatherd saw his goats dance after eating the berries. The scholars of the Saltroad folk took it up to stay awake, and the rulers ban the houses where it is drunk."),
            V("cacao", "A small tree of the rain forest's shade, with large ribbed pods, yellow and red, that grow straight from the trunk. The seeds are fermented and ground into a bitter drink.", "The beans are money: a rabbit costs ten. The drink is for lords and warriors, bitter, with chili."),
            V("kola nut", "A tree of the wet tropical forest with knobbly pods of pink and white nuts, chewed to keep off hunger and sleep and offered to guests.", "The Sunlanders say that he who brings kola brings life. No oath, visit or bargain begins without one being broken and shared."),
            V("betel nut", "A slim, tall palm of hot wet coasts with bunches of orange nuts, sliced and chewed with a leaf and lime. It stains the mouth red.", "A Rainkeeper host offers it before anything is said. Red teeth are the mark of a grown person, and white ones belong to dogs."),
            V("coca", "A shrub of warm mountain valleys with small, thin, bright green leaves, chewed with lime against hunger, cold and thin air.", "The runners of the mountain roads measure distance in the mouthfuls chewed. The leaf is read by diviners."),
            V("tobacco", "A tall plant with huge, sticky leaves and pink trumpet flowers. The leaves are hung to cure brown and are smoked, chewed or snuffed.", "Halflings grow the best leaf and settle disputes over a pipe. Elsewhere the smoke carries prayers upward."),
            V("honey and beeswax", "The stores of the bee, from straw skeps, log hives and wild nests: golden honey in the comb, and yellow wax for candles and seals.", "The bees must be told of a death in the house. The temple takes the wax and the hall takes the mead."),
        ], "Sweet things and things that wake, calm or cheer: sugar, honey, and the leaves, beans and nuts that are brewed, chewed and smoked.", "Small comforts that a people will not give up once it has them. Rulers have learnt that they can be taxed harder than bread."),
        R(Resource.FursAndIvory, "Furs & ivory",
        [
            V("seals", "The skins of seals from cold coasts: short, dense fur, silver-grey and spotted, that sheds water. For boots, cloaks and boat covers.", "The Hoarkin dress in it from the skin out. The seal people of the tales take off the same coat to walk on land."),
            V("whales", "The great beasts of cold seas, hunted from open boats. They give oil for lamps, springy baleen and bone as long as a roof beam.", "A whale on the shore belongs to the ruler: the head to the king and the tail to the queen. The oil lights the cities."),
            V("beaver", "A stout brown water animal with a flat, scaly tail, that dams streams with felled trees. Its dense underfur makes the best felt.", "Its felt makes the hats of every man of standing, and the animal is gone from the settled lands on that account."),
            V("sable and marten", "Slender, quick hunters of the northern forest, with dark brown, silky fur and a pale throat. The fur of princes.", "The soft gold of the north. The forest peoples pay their tribute in it, and a coat is a king's gift to a king."),
            V("squirrel", "The winter coat of the northern squirrel: blue-grey on the back and white on the belly, sewn by the thousand into the linings of robes.", "The grey and white of it is drawn on shields as a pattern of its own. A noble robe takes two thousand bellies."),
            V("ermine", "The stoat in its winter coat: pure white with a black tail tip. Worn by rulers and judges.", "It dies rather than soil its coat, the bestiaries say. It was the fur of the judges of the Old Realms."),
            V("walrus", "A huge, wrinkled, whiskered sea beast of the ice edge, with two long ivory tusks and a hide thick enough for ship's rope.", "The Hoarkin carve its tooth through the dark of the year. The gaming pieces of the Northmen kings are made of it."),
            V("fox and Arctic fox", "The red fox of wood and field, and the white and blue-grey fox of the tundra, taken in winter for their thick fur.", "The trickster of every people's tales. The Hoarkin trade the white pelts south and wonder at what is paid."),
            V("narwhal tusk", "A straight, spiralled ivory tusk, longer than a person, from a small whale of icy seas. Sold in the south as the horn of a unicorn.", "The horn of the unicorn. A cup of it sweats at poison, and kings have paid its weight in gold twenty times over."),
            V("bear", "Great brown and black bears of forest and mountain, and the white bear of the ice. Taken for the pelt, the fat and the claws.", "No northern people says its name aloud: it is the honey eater, the old one in the fur coat. After a kill they ask its pardon."),
            V("elephant ivory", "The long, curved, creamy-white tusks of the elephant. Carved into combs, caskets, thrones and holy images.", "Among the Sunlanders one tusk of every elephant killed is the king's. The altars of his fathers stand on carved tusks."),
            V("ostrich", "A flightless bird of dry plains, taller than a person, that runs faster than a horse. Great soft plumes, black and white, and eggs like ivory bowls.", "A feather of it is the sign of truth, since its vanes are equal on both sides. The eggs hang in temples."),
            V("big cats", "Lions, leopards and tigers: tawny, spotted and striped pelts, with teeth and claws, worn by kings and warriors.", "Only a chief may sit on a leopard skin. The Catfolk will not trade in the pelts, and do not explain."),
            V("exotic feathers", "The bright plumage of tropical birds: scarlet, blue, green and gold, traded in bundles for crowns, cloaks and fans.", "The forest peoples pay their tribute in feathers, and a cloak of them takes ten thousand birds. The birds are plucked and let go."),
            V("musk deer", "A small, hornless deer of cold mountain forest with long fangs. The male carries a pod of musk, the costliest of all scents.", "The Stillfaces, who speak by scent, pay more for musk than any court. A grain of it scents a room for forty years."),
        ], "The costly spoils of wild beasts: fine winter furs, ivory tusks, plumes and musk, brought from forest, ice and savanna by trappers and hunters.", "The law says who may wear which fur, and the forest is emptied to keep the law supplied. Northern peoples pay their tribute in pelts."),
        R(Resource.Dyes, "Dyes",
        [
            V("woad", "A plant with yellow flowers and blue-green leaves, which are crushed, balled and fermented into a blue dye. The vats stink.", "The old Midlander tribes painted themselves blue with it to fight. No woad vat is allowed within a mile of a palace, for the smell."),
            V("madder", "A sprawling, scratchy plant with whorled leaves. Its long red roots are dug in the third year, dried and ground for a strong red.", "The red of soldiers' coats. Fed on it, an animal's bones turn red, and the dyers' own do too."),
            V("weld", "A tall, slender plant with a spike of pale yellow-green flowers. Boiled whole, it gives the clearest yellow.", "Over woad it gives the green of the greenwood, the outlaw's colour."),
            V("indigo", "A bushy tropical plant with small leaves and pink flowers. The leaves are steeped and beaten in vats until a deep blue mud settles, and that is dried into cakes.", "Sunlander dyers are women, and the pits are theirs. The blue rubs off on the skin, and the desert riders wear that as a mark of wealth."),
            V("safflower", "A thistle-like plant with orange-yellow flowers. The petals give a yellow and a pink-red dye, and the seeds an oil.", "The red of the cords that tie the Canal folk's documents. Sold to the unwary as saffron."),
            V("henna", "A shrub of hot dry lands with small leaves that are dried and ground to a green powder. It stains hair, skin and nails red-brown.", "The night of the henna comes before the wedding. A bride does no work until the pattern has worn from her hands."),
            V("annatto", "A tropical shrub with spiky red pods full of seeds coated in an orange-red paste, used to colour food, cloth and skin.", "The forest peoples paint the body with it against insects, spirits and the sun. Strangers took them for a red-skinned race."),
            V("red dyewoods", "Tropical trees whose dense heartwood is deep red. It is shipped in logs and rasped to chips that give reds and purples.", "A country across the ocean is named after the wood. The logs come as ballast and are rasped by prisoners."),
            V("lac", "The crust that tiny insects leave on the twigs of certain trees in the monsoon lands. It is scraped off for a crimson dye and a hard, clear lacquer.", "The seals on a Rainkeeper letter are lac, and so is the shine on the wood. It is counted by the hundred thousand insects."),
            V("cochineal", "A small scale insect that lives on prickly-pear cactus under a white fluff. Dried and crushed, it gives the richest crimson.", "The traders swore it was a seed, and guarded the cactus fields for two centuries. Seventy thousand insects make a pound."),
            V("lichen dyes", "Grey and orange crusts scraped from rock and bark in cold wet lands, and steeped for weeks to give purple, red and brown.", "The island weavers scrape the rocks and steep the crust in stale urine. The cloth keeps the smell for life, and they miss it abroad."),
            V("murex", "Spiny sea snails gathered from rocky shores. Each gives one drop of a dye that turns purple in the sun: the colour of rulers.", "The purple of rulers, worth its weight in silver. A dye town can be smelt across the bay, and its shell heaps are hills."),
            V("kermes", "Small red-brown scale insects, like berries, on the twigs of a low evergreen oak of dry hills. Dried, they give the scarlet of fine cloth.", "The scarlet of a cardinal and a judge. It was long taken for a berry, and it gave its name to crimson."),
        ], "The plants, insects and shells that colour cloth: blue, red, yellow and purple, steeped in vats that stain the dyer's arms.", "Colour is rank: the law keeps purple for the ruler and scarlet for the great. A dye town guards its vats as a mint guards its dies."),
        R(Resource.HorsesAndPackAnimals, "Horses & pack animals",
        [
            V("sled dogs", "Thick-coated, wolf-like dogs with curled tails, that pull sleds over snow and ice in teams and sleep in the open.", "A Hoarkin driver owes the lead dog a share of every kill. In a famine the dogs are eaten last, and the lead dog never."),
            V("reindeer", "Tame reindeer of the far north, broken to pull a sled and carry a pack or a rider. Both sexes bear antlers.", "The only deer that can be ridden. The herders geld the sled animals with their teeth, and will not use a knife."),
            V("donkeys and mules", "Small, long-eared, patient beasts, grey and brown, that carry a pack over stony tracks where no cart can go.", "The mule has no pride of ancestry and no hope of posterity, and carries the world's goods regardless. A priest rides one for humility."),
            V("dromedary camel", "The one-humped, long-legged, sand-coloured camel of hot deserts. It carries a heavy load for days without water.", "The Saltroad folk say it knows the hundredth name of the god and will not tell, which is why it looks as it does."),
            V("Bactrian camel", "The two-humped, shaggy, dark brown camel of cold deserts and high steppe. It bears frost and thirst alike.", "It smells a sandstorm before it comes and buries its nose. The caravans of the cold deserts stop when the old camels kneel."),
            V("llama and alpaca-like camelids", "Woolly, long-necked, humpless beasts of high mountains, in many colours. They carry small loads in long trains and give fine wool.", "It lies down under an unfair load and spits at the one who loaded it. The mountain roads were built to its step, with stairs."),
            V("elephants", "Tamed elephants, grey and huge, with a driver on the neck. They haul timber, carry a tower of fighters and bear kings in procession.", "The Rainkeepers give a driver to one elephant for life. A white one is too holy to work, and its keep can ruin the courtier it is given to."),
            V("horses", "Riding, war and draught horses, from shaggy steppe ponies to tall chargers. The wealth of every lord and rider.", "The Grass riders are in the saddle before they walk, and a man on foot is no man. The Midlander knight is named for his horse."),
        ], "The animals that carry and pull: horses, donkeys, camels and stranger beasts, with saddle, pack and harness. They are what moves an army and a caravan.", "A people's reach is the reach of its beasts. The Grass riders have the horse, the Saltroad folk the camel, and the Rainkeepers the elephant, and each despises walking."),
        R(Resource.Reagents, "Reagents",
        [
            V("alum", "A white, sour-tasting salt in crusts and veins on volcanic ground. It fixes dye to cloth, tans white leather and stops bleeding.", "No cloth takes a dye without it. The temple once held the only mine and banned trade with any other."),
            V("sulphur", "Bright yellow, brittle crystals round steaming vents on volcanoes. It burns with a blue flame and a choking smell.", "Brimstone: the smell of the lower world. It is burnt to cleanse a house after sickness, and it bleaches wool."),
            V("quicksilver", "A liquid, silver metal that runs in heavy beads, roasted from a blood-red stone, cinnabar. The alchemist's first matter, and a poison.", "The alchemists hold every metal to be born of it and sulphur. A Canal folk emperor drank it to live for ever, and is buried among rivers of it."),
            V("alum shale and vitriol", "Dark, crumbling shale that is heaped, burnt and washed for alum, and for green and blue vitriol: the makings of ink, dye and acid.", "The black ink of every charter is made of vitriol and oak galls. It eats the page through in five hundred years."),
            V("saltpetre", "White needle crystals scraped from the crust of dry lake beds in the desert. It makes flame burn fierce, and cures meat.", "The Canal folk call it the snow of their land and make fire flowers of it. Mages and artificers quarrel over who may buy it."),
            V("borax", "A soft, white crystal from the shores of dry desert lakes. It helps gold and silver flow in the goldsmith's fire, and glazes pots.", "It comes down from the high lakes on the backs of sheep, a small bag on each. Goldsmiths will not work without it."),
            V("cave saltpetre", "White, fluffy crusts on the walls and floors of dry limestone caves where bats roost, scraped off and boiled clean.", "The ruler's saltpetre men may dig in any cellar, stable or dovecote, and no one may refuse them."),
        ], "The salts, metals and earths of the dyer, the tanner, the glassmaker and the alchemist: scraped from volcanoes, caves and dry lake beds.", "The dull stuffs that every craft rests on. Alum has caused more wars than gold, and the alchemists get the blame for the smell."),
        R(Resource.Herbs, "Herbs",
        [
            V("gentian", "A mountain plant with deep blue or yellow trumpet flowers. Its thick, bitter root is dug for the stomach.", "Named for a king who found its use. Mountain folk distil the root, and a glass of it settles any dinner."),
            V("arnica", "A mountain-meadow plant with yellow daisy flowers on a hairy stalk. A salve for bruises and sprains.", "Mountain herders smoke the leaf. It is called fall-herb, and every Hearthblood pass warden carries the salve."),
            V("roseroot", "A fleshy, grey-green plant of cold cliffs with yellow flower heads. Its thick root smells of roses when cut, and is chewed against weariness.", "Northmen took it to sea for strength. A bunch of it is given to a couple at their wedding, with a wish for children."),
            V("Iceland moss", "A brown, leathery, curled lichen of the tundra and the heath. Boiled into a jelly for coughs, and as food in famine.", "Ground into the bread of the far north in hungry years. The Hoarkin stew it with seal broth."),
            V("bog myrtle", "A low shrub of cold bogs with scented, grey-green leaves. It flavours ale and keeps off midges.", "The ale of the north was brewed with it before hops came, and the old folk say it was the stronger and the merrier."),
            V("Labrador tea", "A low evergreen shrub of northern bogs, with narrow leaves rusty-woolly beneath and white flowers. Brewed as a strong tea.", "Brewed strong, it makes the head swim. The tanners of the north use it, and the housewives lay it among the clothes against moths."),
            V("yarrow", "A meadow herb with feathery leaves and flat heads of small white flowers. Laid on wounds to stop the blood.", "The soldier's woundwort: a hero taught its use to his men. The Canal folk cast its stalks to read the future."),
            V("wormwood", "A silver-grey, bitter, strongly scented shrub of dry steppe. It drives out worms and flavours strong drink.", "It sprang up in the track of the serpent leaving the garden. The green spirit made with it drives poets mad."),
            V("liquorice", "A bushy plant of dry river plains with feathery leaves. Its long roots are sweet, and are chewed for coughs.", "The Old Realms' soldiers chewed it on the march against thirst. Found in the tomb of a king, in jars."),
            V("ephedra", "A leafless, broom-like shrub of green jointed twigs with red berries, on desert slopes. Brewed for the chest and to stay awake.", "The Canal folk physicians have brewed it for five thousand years. The Grass riders drink it before a long ride."),
            V("chamomile", "A low, feathery plant of fields and waysides with small white daisies that smell of apples. Brewed to calm.", "The plants' physician: a sick shrub recovers with it planted near. The more it is trodden, the more it spreads."),
            V("sage", "A low, woody shrub of dry sunny hills, with soft, grey, wrinkled leaves and violet flowers. For the kitchen and the sickroom.", "Why should a man die who has sage in his garden, the physicians' school asks. It thrives where the wife rules, by the proverb."),
            V("thyme and rosemary", "Low, woody, scented shrubs of dry stony hills: thyme in small cushions with pink flowers, rosemary with dark needles and pale blue flowers.", "Rosemary is for remembrance, worn at weddings and thrown into graves. Thyme gives courage, and ladies embroider it on a knight's scarf."),
            V("poppy", "A tall poppy with grey-green leaves and white or purple flowers. Its green seed head is scratched to bleed a milk that dries brown: it kills pain and brings sleep.", "The gift of the god of sleep. The physicians bless it and the temple warns of it, and both are right."),
            V("hops", "A climbing vine grown up tall poles, with green, papery cones that give ale its bitterness and keep it.", "The brewers of unhopped ale called it a wicked weed and had it banned. The hopped beer kept longer, and won."),
            V("valerian", "A tall plant of damp meadows with pale pink flower heads. Its strong-smelling root brings sleep, and draws cats.", "The ratcatcher's secret: rats follow it, as cats do. All-heal, by its other name."),
            V("St John's wort", "A wayside plant with yellow, star-like flowers that bleed red when crushed. An oil for wounds and a tea for a heavy heart.", "Gathered on midsummer morning and hung over the door, it keeps out witches, lightning and melancholy."),
            V("foxglove", "A tall spire of purple, spotted bells at the edge of woods. A medicine for the heart in a small dose, a poison in a larger.", "The gloves of the good folk, who gave them to the fox to soften his step. The village herbalist knew its use on the heart long before the physicians."),
            V("comfrey", "A coarse, hairy plant of damp ground with drooping purple bells. Its root and leaves are bound on broken bones.", "Knitbone. The Flinchless surgeons and the village bonesetter both pack a break with it."),
            V("angelica", "A plant taller than a person, with hollow stems and great round heads of greenish flowers, in wet ground. Candied, and taken against plague.", "An angel showed it to a monk in a plague year. The Northmen have had a law since their beginning against stealing it from a garden."),
            V("aloe", "A rosette of thick, fleshy, spiny-edged leaves on dry ground. They hold a clear gel for burns and a bitter yellow sap that purges.", "A conqueror was told to take an island for the sake of its aloes, to heal his soldiers. Hung over a Saltroad door, it lives on air."),
            V("senna", "A low desert shrub with yellow flowers and flat pods. Leaves and pods are brewed as a purge.", "The Saltroad physicians brought it into medicine. Every caravan carries it, and children dread it."),
            V("devil's claw", "A creeping plant of dry sandy savanna with pink trumpet flowers and a fruit of hooked claws. Its tubers ease aching joints.", "The hooked fruit catches in a beast's hoof to be carried. The hunters of the dry savanna dig the root in secret places."),
            V("neem", "A large, evergreen shade tree of dry tropical land. Its bitter leaves, bark and oil clean teeth, heal the skin and drive off insects.", "The village pharmacy of the Rainkeepers. A twig of it is the toothbrush of a whole people, and its leaves are strewn where there is pox."),
            V("holy basil", "A small, hairy, scented bush with purple-tinged leaves, grown in a pot by the door and at shrines. Brewed against fever.", "A goddess in the form of a plant. Rainkeeper houses are built around the pot it grows in, and it is watered at dawn."),
            V("fever bark", "A tree of wet tropical mountain forest. Its bitter, red-brown bark is stripped, dried and ground against the shaking fever.", "The mountain people saw a sick puma drink from a pool under the tree. The Bitterbloods gather it and sell the cure for the shaking fever."),
            V("ipecac", "A small shrub of the rain forest floor. Its thin, ringed roots bring on vomiting and cure the bloody flux.", "The forest healers call it the roadside sick-making plant, and sell the secret dearly."),
            V("arrow-poison vine", "A thick, woody vine that climbs to the canopy of the rain forest. Its bark is boiled down to a black paste that stills the muscles.", "Each forest family has its own recipe, and the Bitterbloods the best. The strength is told in trees: how many a monkey can leap before it falls."),
            V("water hyssop", "A small, creeping, fleshy herb with pale flowers, on the mud of warm marshes and mangrove edges. Taken to sharpen the memory.", "Rainkeeper pupils are given it to learn the long texts by heart. It is offered to the god who made the world."),
        ], "The plants of the healer, the brewer and the alchemist, not of the kitchen: roots, leaves, barks and flowers, gathered wild and dried in bunches.", "Every plant is a medicine or a poison, and the dose decides. The village healer and the Bitterblood apothecary know the same herbs by different names."),
        R(Resource.ArcaneMaterials, "Arcane materials",
        [
            V("star metal", "Iron that fell from the sky: black, pitted, heavy lumps with a melted crust, lying in sand or on ice round an old crater. Cut, it shows a silver, criss-cross grain. It is forged cold, and a blade of it turns magic aside.", "A king's dagger of it was laid in his tomb when iron was still unknown. The Grass riders do not touch a fallen star for a year, and then only the smith may."),
            V("truesilver", "A white metal, lighter than steel and harder, that never tarnishes. It runs as bright threads through the granite of high mountains, and melts only in the hottest forge. Drawn into wire, it sings.", "The Dwarves say the sorcerer-kings mined the last great veins and that what is found now is crumbs. They do not say where the crumbs are."),
            V("mana crystal", "Clear crystals with a slow inner glow, violet to blue, that line hollow stones in wet volcanic ground. They hold magic as a jar holds water, and are cut as the focus stones of mages.", "A college of mages buys every stone it hears of, and counts the unsold ones as a threat. The crystals dim in the hand of someone dying."),
            V("dragonbone", "The stone bones of the great dragons, weathering out of dry sandstone hills: ribs like ship's timbers, dark and heavy, with a dull red sheen. Lighter and tougher than steel when worked.", "Dwarves mine it only after buying the hill from its drake, with a goat a week. The Midlanders show a rib of it in a church as the bone of a giant."),
            F("glowcap fungi", "glowcap"),
            V("moonpearls", "Large pearls of a pale blue-white that shine with their own light in the dark, as the full moon does. They grow in the moon oyster, a giant shell of warm shallow seas that opens only under a full moon. Used for scrying.", "A Shoalfolk diver who brings up a moonpearl may name the price of the family's reef. Lanternkin envoys wear one, and it is said to dim at a lie."),
            F("frost-lotus", "frostLotus"),
            V("windcrystal", "A pale, blue-white crystal, like frozen breath, that grows on the highest and coldest peaks and hums when the wind crosses it. A piece of it weighs less than nothing and tugs upward in the hand.", "Hearthbloods say it is the breath of the frost drake, frozen in the rock. Miners listen for the drake before they dig."),
            V("sunstone", "A warm, amber-gold stone found in the hottest sands of the desert. It drinks the heat of the day and gives it back through the night, glowing like an ember.", "The Saltroad caravans carry one in the bedding for the desert night. It is found in the ash of a phoenix, the incense merchants say, and each has a cousin who saw it."),
            F("elderwood", "elderwood"),
            F("sap of Elanor", "elvenSapflower"),
            F("dreamleaf", "dreamleaf"),
            V("ghostlight peat", "Black peat from bogs where pale lights dance at night. A brick of it burns with a cold, blue, smokeless flame that gives light and no heat, and draws no beast.", "The lights over the bog are the lanterns of the drowned. A mage pays for the peat by the basket, and the peat cutters cross themselves and take the money."),
            V("stormglass", "Twisted tubes and beads of grey-green glass, made where lightning strikes the open plain. A faint light flickers inside them, and brightens before a storm.", "The Widegaze see the grey birds gather a day before the storm and know where the glass will be. Herders bury a bead of it under the threshold of the winter fold."),
        ], "Things that hold magic: strange metals, glowing crystals, old bones and plants that should not be, found only where the Supernatural is strong. Rare, costly, and sought by mages, alchemists and artificers.", "The sorcerer-kings of the Old Realms built their power on these and mined out what they found. What is left lies where the world is still strange, and a college, a crown and a cabal will each pay to hear of a new find."),
    ];
}
